use desafio::consulta;
use std::collections::HashMap;

#[test]
fn testa_a_idade_da_ana() {
    let mut idades = HashMap::new();
    idades.insert(String::from("ana"), 9);
    assert_eq!(consulta(&idades, "ana"), Some(9));
}

#[test]
fn testa_a_chave_que_nao_existe() {
    let mut idades = HashMap::new();
    idades.insert(String::from("bo"), 4);
    assert_eq!(consulta(&idades, "ana"), None);
}
